#include "olb2D.h"
#include "olb2D.hh"
#include <algorithm>
#include <cmath>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <stdexcept>
#include <string>
#include <vector>
using namespace olb; using namespace olb::descriptors; using namespace olb::names; using T=double;
using NSD=D2Q9<RHO,NABLARHO,FORCE,EXTERNAL_FORCE,TAU_EFF,STATISTIC,SCALAR>;
using CHD=D2Q9<CONV_POPS,FORCE,SOURCE,VELOCITY,OLD_PHIU,STATISTIC,THETA,BOUNDARY>;
using Op=LiangPostProcessor;
using Maps=meta::map<NavierStokes,descriptors::VALUED_DESCRIPTOR<T,NSD>,Component1,descriptors::VALUED_DESCRIPTOR<T,CHD>>;
using CP=SuperLatticeCoupling<Op,Maps>;
struct Opt{int nx=50,ny=50,x0=8,single=0;long steps=80000,diag=400,out=10000;T dx=2e-6,theta=60,rL=1000,rG=10,nu=1e-6,sigma=1e-4,tau=.8,w=5,pressureFactor=1.3;};
Opt parse(int n,char**v){Opt o;for(int i=1;i<n;i++){std::string a=v[i],x=v[++i];if(a=="--steps")o.steps=stol(x);else if(a=="--pressure-factor")o.pressureFactor=stod(x);else if(a=="--theta")o.theta=stod(x);else if(a=="--single-phase")o.single=stoi(x);else if(a=="--diagnostic-every")o.diag=stol(x);else if(a=="--output-every")o.out=stol(x);else throw std::runtime_error("bad option");}return o;}
class Front:public AnalyticalF2D<T,T>{T x,w;public:Front(T a,T b):AnalyticalF2D<T,T>(1),x(a),w(b){}bool operator()(T z[],const T p[])override{z[0]=.5*(1-tanh(2*(p[0]-x)/w));return true;}};
class Phi:public SuperF2D<T,T>{SuperLattice<T,CHD>&l;public:Phi(SuperLattice<T,CHD>&q):SuperF2D<T,T>(q,1),l(q){this->getName()="phi";}bool operator()(T z[],const int p[])override{auto&b=l.getLoadBalancer();if(!b.isLocal(p[0]))return false;z[0]=l.getBlock(b.loc(p[0])).get(p[1],p[2]).template getFieldComponent<STATISTIC>(0);return true;}};
T front(SuperGeometry<T,2>&geo,SuperLattice<T,CHD>&ch){auto&g=geo.getBlockGeometry(0);auto&c=ch.getBlock(0);std::vector<std::pair<T,T>> row;g.forSpatialLocations([&](LatticeR<2>q){auto x=g.getPhysR(q);if(g.get(q)==1&&!c.isPadding(q)&&std::abs(x[1]-50e-6)<.25e-6)row.push_back({x[0],c.get(q).template getFieldComponent<STATISTIC>(0)});});std::sort(row.begin(),row.end());T xf=NAN;for(std::size_t i=1;i<row.size();++i)if(row[i-1].second>=.5&&row[i].second<.5)xf=row[i-1].first+(.5-row[i-1].second)/(row[i].second-row[i-1].second)*(row[i].first-row[i-1].first);return xf;}
struct FlowSample{T meanUx{},pLeft{},pRight{},meanTau{},meanPhi{};int n{},nl{},nr{};};
FlowSample sampleFlow(SuperGeometry<T,2>&geo,SuperLattice<T,NSD>&ns,SuperLattice<T,CHD>&ch,T lx,T pressureFactor){FlowSample s;auto&g=geo.getBlockGeometry(0);auto&l=ns.getBlock(0);auto&c=ch.getBlock(0);g.forSpatialLocations([&](LatticeR<2>q){if(g.get(q)!=1||l.isPadding(q))return;auto x=g.getPhysR(q);T u[2]{};l.get(q).computeU(u);s.meanUx+=u[0];s.meanTau+=l.get(q).template getFieldComponent<TAU_EFF>(0);s.meanPhi+=c.get(q).template getFieldComponent<STATISTIC>(0);++s.n;T p=l.get(q).computeRho()*pressureFactor;if(x[0]<2.5e-6){s.pLeft+=p;++s.nl;}if(x[0]>lx-3.5e-6){s.pRight+=p;++s.nr;}});if(s.n){s.meanUx/=s.n;s.meanTau/=s.n;s.meanPhi/=s.n;}if(s.nl)s.pLeft/=s.nl;if(s.nr)s.pRight/=s.nr;return s;}
int main(int argc,char**argv){initialize(&argc,&argv);Opt o=parse(argc,argv);T lx=o.nx*o.dx,ly=o.ny*o.dx,H=(o.ny-1)*o.dx,x0=o.single?2*lx:o.x0*o.dx,rg=o.rG/o.rL;
 IndicatorCuboid2D<T>d({lx,ly},{0,0});CuboidDecomposition2D<T>cub(d,o.dx,1);HeuristicLoadBalancer<T>load(cub);SuperGeometry<T,2>g(cub,load,2);g.rename(0,2);g.rename(2,1,{1,1});IndicatorCuboid2D<T>lower1({6*o.dx,22*o.dx},{12*o.dx,0}),upper1({6*o.dx,22*o.dx},{12*o.dx,28*o.dx}),lower2({6*o.dx,22*o.dx},{30*o.dx,0}),upper2({6*o.dx,22*o.dx},{30*o.dx,28*o.dx});g.rename(1,2,lower1);g.rename(1,2,upper1);g.rename(1,2,lower2);g.rename(1,2,upper2);IndicatorCuboid2D<T>ii({o.dx,ly-2*o.dx},{-.5*o.dx,o.dx}),oo({o.dx,ly-2*o.dx},{lx-.5*o.dx,o.dx});g.rename(2,3,ii);g.rename(2,4,oo);g.clean();g.innerClean();g.checkForErrors();g.print();
 SuperLattice<T,NSD>ns(g);SuperLattice<T,CHD>ch(g);CP cp(Op{},NavierStokes{},ns,Component1{},ch);ns.setUnitConverter<MultiPhaseUnitConverterFromRelaxationTime<T,NSD>>(o.ny-1,o.tau,1.,H,o.nu,o.rL);ch.setUnitConverter(ns.getUnitConverter());auto&cv=ns.getUnitConverter();T sig=o.sigma/cv.getConversionFactorSurfaceTension();auto bulk=g.getMaterialIndicator(1),wall=g.getMaterialIndicator(2),in=g.getMaterialIndicator(3),out=g.getMaterialIndicator(4),fluid=g.getMaterialIndicator({1,3,4}),all=g.getMaterialIndicator({0,1,2,3,4});
 dynamics::set<MultiPhaseIncompressibleBGKdynamics<T,NSD>>(ns,bulk);dynamics::set<ConservativePhaseFieldBGKdynamics<T,CHD>>(ch,bulk);boundary::set<boundary::BounceBackIncompressible>(ns,wall);boundary::set<boundary::PhaseFieldCurvedWall>(ch,wall);boundary::set<boundary::IncompressibleZouHePressure>(ns,in);boundary::set<boundary::IncompressibleZouHePressure>(ns,out);boundary::set<boundary::RegularizedTemperature>(ch,in);setConvectivePhaseFieldBoundary<T,CHD>(ch,out);
 ch.addPostProcessor<stage::PreCoupling>(fluid,meta::id<RhoStatistics>());ch.addPostProcessor<stage::InitOutlet>(out,meta::id<SetOutletCells2D<1,0>>());cp.restrictTo(g.getMaterialIndicator({1,4}));cp.setParameter<Op::SIGMA>(sig);cp.setParameter<Op::W>(o.w);cp.setParameter<Op::TAUS>({T(.53),o.tau});cp.setParameter<Op::RHOS>({rg,1.});cp.setParameter<Op::SWITCH>(1.);ns.setParameter<OMEGA>(1/o.tau);ch.setParameter<OMEGA>(1/o.tau);ch.setParameter<INTERFACE_WIDTH>(o.w);ch.setParameter<THETA>(o.theta*M_PI/180);ch.setParameter<EPSILON>(1.5*o.w);auto&comm=ch.getCommunicator(stage::PreCoupling());comm.requestOverlap(1);comm.requestField<STATISTIC>();comm.exchangeRequests();
T throatH=6*o.dx,threshold=2*o.sigma*std::cos(o.theta*M_PI/180)/throatH,capillaryPressure=o.pressureFactor*threshold;
Front ph(x0,o.w*o.dx); AnalyticalConst2D<T,T> z(0),one(1),two(2),u(Vector<T,2>{0,0}),r0(rg),dr(1-rg),tg(.53),dTau(o.tau-.53),pInPhys(capillaryPressure); AnalyticalIdentity2D<T,T> rho(r0+dr*ph),tau(tg+dTau*ph);
fields::set<RHO>(ns,all,rho); fields::set<TAU_EFF>(ns,all,tau); fields::set<SCALAR>(ns,all,one); fields::set<SCALAR>(ns,wall,two); fields::set<BOUNDARY>(ch,fluid,one); fields::set<BOUNDARY>(ch,wall,two); AnalyticalConst2D<T,T> wallTheta(o.theta*M_PI/180);fields::set<THETA>(ch,wall,wallTheta);fields::set<OLD_PHIU>(ch,all,u);
momenta::setOrderParameter(ch,all,ph); momenta::setOrderParameter(ch,in,one); momenta::setIncompressiblePressure(ns,all,z); momenta::setVelocity(ns,all,u);
ns.iniEquilibrium(all,z,u); ch.iniEquilibrium(all,ph,u); ns.initialize(); ch.initialize(); ch.iniEquilibrium(all,ph,u); ns.iniEquilibrium(all,z,u);
momenta::setIncompressiblePressure(ns,in,pInPhys); momenta::setIncompressiblePressure(ns,out,z); momenta::setOrderParameter(ch,in,one); ch.executePostProcessors(stage::InitOutlet()); comm.communicate();
ns.setProcessingContext(ProcessingContext::Simulation); ch.setProcessingContext(ProcessingContext::Simulation);
 std::ofstream f("small_pore_diagnostics.csv");f<<std::setprecision(17)<<"step,time_s,front_m,second_throat_exit_m,pressure_factor,threshold_Pa,max_speed_lattice,mean_ux_lattice,liquid_saturation\n";Phi po(ch);SuperLatticePhysVelocity2D<T,NSD>vel(ns,cv);vel.getName()="velocity_phys_m_s";SuperVTMwriter2D<T>w("small_pore_model");w.addFunctor(po);w.addFunctor(vel);w.createMasterFile();
 for(long s=0;s<=o.steps;s++){if(s){ns.collideAndStream();ch.collideAndStream();comm.communicate();ch.executePostProcessors(stage::PreCoupling());comm.communicate();cp.apply();}if(s%o.diag==0||s==o.steps){T x=front(g,ch),um=ns.getStatistics().getMaxU();auto fs=sampleFlow(g,ns,ch,lx,cv.getConversionFactorPressure());f<<s<<','<<cv.getPhysTime(s)<<','<<x<<','<<36*o.dx<<','<<o.pressureFactor<<','<<threshold<<','<<um<<','<<fs.meanUx<<','<<fs.meanPhi<<'\n';}if(s%o.out==0||s==o.steps){w.write((int)s);std::cout<<"step="<<s<<" front="<<front(g,ch)<<'\n';}}
 std::ofstream c("run_config.csv");c<<std::setprecision(17)<<"throat_gap_m,theta_deg,dx_m,dt_s,sigma_N_m,threshold_Pa,applied_pressure_Pa,pressure_factor\n"<<throatH<<','<<o.theta<<','<<o.dx<<','<<cv.getPhysDeltaT()<<','<<o.sigma<<','<<threshold<<','<<capillaryPressure<<','<<o.pressureFactor<<'\n';}
